import {renderGrowthTags} from './growth-tags.js';
import {RevealTiming} from './reveal-timing.js';
import {rank,growthOwners} from './growth.js';
import {CharacterDetails} from './details.js';
import {CHARS,byId} from './data.js';
import {WORLD,CAMPS} from './world.js';
import {xpForLevel,TRIAL_TICKET_CAP} from './balance.js';
import {TimingGame} from './minigame.js';
const newIcons=import.meta.glob('./assets/icons/*.png',{eager:true,query:'?url',import:'default'});
const $=s=>document.querySelector(s);
export class UI{
 constructor(e,r){this.e=e;this.r=r;this.mini=null;this.dragId=null;this.soundOn=false;this.lastAudio=0;this.details=new CharacterDetails(this);this.bind();this.refresh();this.paintSprites();}
 sprite(id,cls='avatar'){return `<div class="${cls}" data-sprite="${id}" aria-label="${id?byId(id)?.name:'穹'}"></div>`;}
 paintSprites(){document.querySelectorAll('[data-sprite]').forEach(el=>{let id=+el.dataset.sprite;const icon=newIcons[`./assets/icons/${id}.png`];if(icon){el.style.backgroundImage=`url("${icon}")`;el.style.backgroundSize='contain';el.style.backgroundRepeat='no-repeat';el.style.backgroundPosition='center';return;}el.style.backgroundPosition=`${(id%4)*100/3}% ${Math.floor(id/4)*100/3}%`;});}
 bind(){const player=$('.playerpanel');player.tabIndex=0;player.setAttribute('role','button');player.setAttribute('aria-label','查看穹的成长光锥');player.onclick=()=>this.details.open(0);player.onkeydown=ev=>{if(ev.key==='Enter')this.details.open(0);};window.addEventListener('pointerdown',ev=>{if(this.e.modal==='reveal'){ev.preventDefault();ev.stopImmediatePropagation();this.revealClickUntil=performance.now()+500;this.requestRevealExit();}},true);window.addEventListener('click',ev=>{if(this.e.modal==='reveal'){ev.preventDefault();ev.stopImmediatePropagation();this.requestRevealExit();return;}if(performance.now()<(this.revealClickUntil||0)){ev.preventDefault();ev.stopImmediatePropagation();return;}if(this.e.modal==='upgrade'&&!ev.target.closest('#modal')&&!(import.meta.env.DEV&&ev.target.closest('[data-dev-checks]'))){ev.stopImmediatePropagation();ev.preventDefault();}},true); $('#partyhud').onclick=ev=>{const b=ev.target.closest('button');if(!b)return;b.dataset.id?this.details.open(+b.dataset.id):this.openParty();};$('#party').onclick=()=>this.openParty();$('#warp').onclick=()=>this.openWarp();$('#help').onclick=()=>this.help();$('#pause').onclick=()=>this.pause();$('#dash').onclick=()=>this.e.dash();$('#interact').onclick=()=>this.e.interact();$('#sound').onclick=()=>{this.soundOn=!this.soundOn;$('#sound').textContent=this.soundOn?'♫ 声音开':'♫ 声音关';if(this.soundOn)this.audio('heal');};$('#modal .scrim').onclick=()=>{if(!['upgrade','photo','fish','slots'].includes(this.e.modal))this.close();};document.addEventListener('keydown',ev=>{if(ev.key==='Escape'){ev.preventDefault();if(this.e.modal==='reveal'){this.requestRevealExit();return;}if(this.e.modal==='upgrade')return;if(this.e.modal)this.close();else this.pause();}if(ev.key==='Tab'){ev.preventDefault();if(this.e.modal==='party')this.close();else if(!this.e.modal)this.openParty();}});$('#minimap').onclick=ev=>{if(this.e.modal)return;let b=ev.currentTarget.getBoundingClientRect();this.e.target={x:(ev.clientX-b.left)/b.width*WORLD.w,y:(ev.clientY-b.top)/b.height*WORLD.h};this.e.toast('已设置目标。遇到房屋或湖岸时，可用方向键绕行。');};}
 modal(type,title,eyebrow,body,foot=''){this.e.setModal(type);$('#modal').hidden=false;$('#modalcontent').innerHTML=`<div class="modalhead"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1></div>${type==='upgrade'?'':`<button class="close" aria-label="关闭">×</button>`}</div>${body}${foot?`<div class="modalfoot">${foot}</div>`:''}`;const close=$('#modalcontent .close');if(close)close.onclick=()=>this.close();this.paintSprites();setTimeout(()=>$('#modalcontent button')?.focus(),0);}
 close(){if(this.e.modal==='reveal'){this.requestRevealExit();return;}this.details.close();this.mini=null;$('#modal').hidden=true;this.e.close();this.refresh();}
 refresh(){const e=this.e;$('#tickets').textContent=`专票 × ${e.tickets}`;$('#coins').textContent=`◈ ${e.coins}`;$('#count').textContent=`同行伙伴 ${e.team.length} / 6`;$('#state').textContent=e.combat?'⚔ 自动战斗中':'✦ 自由探索';const hudKey=e.team.map(id=>id+':'+e.members[id].level).join(',');if(this.hudKey!==hudKey){this.hudKey=hudKey;$('#partyhud').innerHTML=Array.from({length:6},(_,i)=>{let id=e.team[i];if(!id)return '<button class="hudchar empty" title="编队空位">＋</button>';let c=byId(id),m=e.members[id];return `<button class="hudchar" data-id="${id}" title="${c.name} · ${c.role}：${c.desc}">${this.sprite(id)}<span class="lv">Lv.${m.level}</span><span class="name">${c.name}</span><i class="cooldown" data-cd="${id}"></i></button>`;}).join('');this.paintSprites();}$('.chapter').textContent=e.mapId==='starfield'?'第二章 · 星潮旷野':'第一章 · 林间的来信';$('.questpanel h2').textContent=e.mapId==='starfield'?'无尽的星潮':'林间的来信';$('#questtext').textContent=e.mapId==='starfield'?'向东进入开阔战场；西侧归航营地可返回驿站。':e.quest===3?'与驿站站务员交谈，传送至星潮旷野。':e.bossDead?'返回驿站，向林恩报告净化结果':e.quest===0?'与驿站的站务员交谈':'前往地图最东端，接触守门者即可开战';$('#questprogress').textContent=e.mapId==='starfield'?'分层挑战 · 首领掉落黄金光锥':e.quest===3?'✓ 林间的来信 · 已完成':e.quest>0&&!e.bossDead?`星轨碎片 ${e.fragments} / 3`:' ';}
 card(id,slot=null,locked=false){let c=byId(id);if(!c)return `<div class="charcard empty" data-slot="${slot}">＋<small>空闲位置</small></div>`;return `<button class="charcard ${locked?'locked':''}"  draggable="${!locked}" data-id="${id}" ${slot!==null?`data-slot="${slot}"`:''} title="${c.skill}：${c.desc}"><span class="card-level">Lv.${this.e.members[id].level}</span><span class="rarity">${c.star}★</span>${this.sprite(id)}<b>${c.name}</b><small>${c.element} · ${c.role}</small></button>`;}
 openParty(){if(['upgrade','reveal'].includes(this.e.modal))return;const e=this.e;this.modal('party','同行的伙伴','TRAILBLAZE TOGETHER',`<p class="modalnote">拖动背包角色到上场栏进行替换；拖动上场角色调整顺序。点击角色查看详情；详情中可加入或移出队伍。</p><div class="sectionlabel">上场角色 <small>${e.team.length} / 6 · 穹始终在队</small></div><div class="slots">${Array.from({length:6},(_,i)=>this.card(e.team[i],i)).join('')}</div><div class="sectionlabel">角色背包 <small>已重逢 ${e.owned.length} / ${CHARS.length}</small></div><div class="roster" id="backpack">${CHARS.filter(c=>!e.team.includes(c.id)).map(c=>this.card(c.id,null,!e.owned.includes(c.id))).join('')}</div>`,`<small>同伴不会受伤。技能会在移动中自动释放。</small><button class="action" id="partyDone">完成编队</button>`);$('#partyDone').onclick=()=>this.close();document.querySelectorAll('.charcard[data-id]').forEach(b=>{b.onclick=()=>this.details.open(+b.dataset.id);b.ondragstart=ev=>{this.dragId=+b.dataset.id;ev.dataTransfer.setData('text/plain',b.dataset.id);ev.dataTransfer.effectAllowed='move';};});document.querySelectorAll('[data-slot]').forEach(b=>{b.ondragover=ev=>{ev.preventDefault();b.style.borderColor='#a98c47';};b.ondragleave=()=>b.style.borderColor='';b.ondrop=ev=>{ev.preventDefault();let id=+ev.dataTransfer.getData('text/plain');if(e.owned.includes(id)){e.equip(id,+b.dataset.slot);this.openParty();}};});$('#backpack').ondragover=ev=>ev.preventDefault();$('#backpack').ondrop=ev=>{if(ev.target.closest('[data-slot]'))return;ev.preventDefault();const id=+ev.dataTransfer.getData('text/plain');if(e.team.includes(id)){e.equip(id);this.openParty();}};}
 openWarp(){if(['upgrade','reveal'].includes(this.e.modal))return;this.mini=null;let e=this.e,full=e.owned.length===CHARS.length,canGrow=growthOwners(e).length>0;this.modal('warp','与星光重逢','STELLAR WARP',`<div class="warp-banner"><div class="eyebrow">失散的讯号 · 常驻跃迁</div><h2>下一站，是熟悉的身影。</h2><p>21 位伙伴等待重逢，包含全新加入的 10 位五星角色。<br>${full?'专票可以继续用于抽取成长光锥。':'每张星轨专票都会带回一位尚未重逢的伙伴。'}<br>已拥有角色不会重复出现。</p></div><div class="collection">${CHARS.map(c=>`<div class="${e.owned.includes(c.id)?'owned':''}">${this.sprite(c.id)}<small>${c.name}</small></div>`).join('')}</div><p class="modalnote">${full?(canGrow?'所有伙伴已重逢。可消耗专票选择光锥：优先上场伙伴，满成长后转向场下伙伴。':'所有伙伴与光锥均已集齐，专票会保留。'):`已重逢 ${e.owned.length} / ${CHARS.length} 位伙伴。上场未满六人时，新伙伴会自动加入编队。`}</p>`,`<small>星轨专票 <b>× ${e.tickets}</b>　·　游戏已暂停</small><button class="action gold" id="pull" ${e.tickets<1||full&&!canGrow?'disabled':''}>${full?'✦ 光锥抽取':'✦ 跃迁一次'} · 消耗 1 张</button>`);$('#pull').onclick=()=>{if(full){if(e.useTicketGrowth()){$('#modal').hidden=true;this.refresh();this.syncUpgrade();}return;}let c=e.recruit();if(c)this.reveal(c);};}
 reveal(c){const joined=this.e.team.includes(c.id);this.revealTiming=new RevealTiming(performance.now());this.modal('reveal','熟悉的身影','NEW COMPANION',`<div class="reveal summon-reveal"><div class="summon-rays"></div><div class="stars">${'★'.repeat(c.star)}</div>${this.sprite(c.id)}<h2>${c.name}</h2><div class="eyebrow">${c.element} · ${c.role}</div><p><b>${c.skill}</b><br>${c.desc}</p><p class="modalnote">${joined?'已加入编队，正在你身边等候。':'已加入角色背包，可在队伍界面调整上场。'}</p></div>`,`<button class="action gold" id="revealContinue">星光正在汇聚…</button>`);this.audio('lord');this.refresh();}
 requestRevealExit(){if(this.e.modal!=='reveal')return;this.revealTiming?.request(performance.now());this.finishReveal();}
 finishReveal(){if(this.e.modal!=='reveal'||!this.revealTiming?.consume(performance.now()))return;this.revealTiming=null;$('#modal').hidden=true;this.e.finishSummon();this.refresh();this.syncUpgrade();}
 syncUpgrade(){const u=this.e.upgrades[0];if(this.e.modal==='upgrade'&&u?.choices&&(this.displayedUpgrade!==u||$('#modal').hidden)){this.upgrade(u);}}
 upgrade(u){this.displayedUpgrade=u;const e=this.e,choices=u.choices;this.modal('upgrade',u.gold?'首领战利品 · 黄金光锥':`${u.id?byId(u.id).name:'穹'} · ${u.source==='ticket'?'车票赠礼':'Lv.'+u.level}`,'LIGHT CONE · 光锥共鸣',`<p class="modalnote growth-rule">${u.gold?`通关奖励：优先上场伙伴的黄金光锥，抽满后转向场下伙伴。${u.advance?'选完后进入下一层。':'选完后可启程前往无尽战场。'}`:u.id?(u.fixed?'重逢赠礼：本次光锥属于刚召唤的伙伴。':'车票赠礼：优先选择尚未满成长的上场伙伴，之后选择场下伙伴。'):'开拓者晋升：优先保留穹的成长，其余来自尚未满成长的上场伙伴。'}<br>选择一张立即生效 · 每张最多叠至 III 级 · 换人后仍保留</p><div class="growth-choices">${choices.map((card,i)=>{const actor=card.owner?e.members[card.owner]:e.hero,n=rank(actor,card.key),next=n+1;return `<button class="light-cone ${card.gold?'legendary':'ordinary'} ${card.supply?'supply':''}" style="--delay:${i*100}ms" data-choice="${i}" aria-label="选择${card.owner?byId(card.owner).name:'穹'}的${card.name}"><div class="cone-rarity">${card.supply?'旅途补给':card.gold?'✦ 黄金成长':'✧ 普通成长'}</div><div class="cone-art"><div class="cone-orbit"></div>${this.sprite(card.owner)}<span class="cone-emblem">${card.gold?'✦':'◇'}</span></div><span class="cone-owner">${card.owner?byId(card.owner).name:'穹 · 开拓者'}${!u.id&&!u.gold&&i===0&&card.owner===0&&!card.supply?' · 固定席':''}</span><h2>${card.name}</h2>${renderGrowthTags(card)}<div class="cone-rank">${card.supply?'卡池补充':n?`${['','I','II','III'][n]} → ${['','I','II','III'][next]}`:'新成长 · I'}${!card.supply?` <small>${next} / 3</small>`:''}</div><p>${card.describe(next)}</p><span class="cone-select">${card.supply?'领取补给':n?'强化这张光锥':'获得这张光锥'}</span></button>`;}).join('')}</div>`,`<small>Ⅱ 世界与战斗已暂停 · 待选 ${e.upgrades.length} 次 · 选完全部后自动继续</small>`);document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{if(e.upgrades[0]!==u)return;if(e.chooseUpgrade(+b.dataset.choice)){$('#modal').hidden=true;this.audio('heal');this.refresh();}});}
 station(){const e=this.e;if(e.quest===0){this.modal('station','晴岚驿站的来信','林恩 · 站务员',`<div class="dialogue">${this.sprite(10)}<p>“你也是从那列没有轨道的列车上下来的？”<br><span class="modalnote">林恩递来一封信。信纸上，三段断裂的金色轨迹仍在发光。</span><br>“林径的裂界生物带走了锚点碎片。找齐三枚，把最东端遗迹的星轨重新点亮，失散的伙伴就能听见我们。”</p></div>`,`<small>目标：向东探索 → 接触守门者开战 → 净化守门者</small><button id="accept" class="action gold">接下这封信</button>`);$('#accept').onclick=()=>{e.quest=1;e.receiveTickets(1);e.toast('收到了备用星轨专票 ×1。可以在跃迁界面呼唤伙伴。');this.close();};}else if(e.bossDead&&e.quest!==3){this.modal('station','轨道的另一端','第一章 · 完成',`<div class="dialogue">${this.sprite(10)}<p>驿站的星灯依次亮起。列车的汽笛第一次穿过了森林。<br>“这次，信终于送到了。”<br><span class="modalnote">三月七将新的合影贴在站台上。丹恒收起长枪，望向远方。失散的旅程，还会继续。</span></p></div>`,`<small>委托奖励：信用点 +100，星轨专票 ×3</small><button class="action gold" id="complete">收下回信</button>`);$('#complete').onclick=()=>{e.quest=3;e.coins+=100;e.receiveTickets(3);this.close();e.toast('第一章已完成！驿站已解锁星潮旷野传送。');this.station();};}else if(e.quest===3){this.modal('station','启程 · 星潮旷野','第二章 · 无尽战场',`<div class="dialogue">${this.sprite(10)}<p>星轨已接通远方的归航营地。<br><span class="modalnote">宽阔旷野上有 四面来敌的分层战场：每层击败 200 / 500 / 5000 名敌人后出现首领，之后每层增加 500 名。首领战后奖励黄金光锥，并进入更强的一层。角色、等级、编队和物品会随你同行。</span></p></div>`,`<small>可从旷野的归航营地返回驿站。</small><button class="action gold" id="depart">传送至星潮旷野</button>`);$('#depart').onclick=()=>{if(e.travel('starfield'))this.close();};}else{this.modal('station','星灯仍在等候','林恩 · 站务员',`<p class="modalnote">${e.quest===3?'“谢谢你，开拓者。晴岚驿站永远欢迎你和伙伴们回来。”':'“沿着驿站东边的路，向南绕过树林，再向东北走。带金色标记的精英身上有锚点碎片。”'}</p>`,`<small>驿站内会自动恢复穹的生命。</small><button class="action" id="ok">继续旅程</button>`);$('#ok').onclick=()=>this.close();}}
 chapterComplete(){this.modal('chapter','第一章 · 完成','星轨已连通',`<p class="modalnote">裂界守门者已被击败，任务自动完成。<br>已获得 100 信用点与 3 张车票。是否现在进入分层无尽战场？也可稍后从驿站找林恩传送。</p>`,`<button class="action secondary" id="later">继续探索</button><button class="action gold" id="enterTrial">进入无尽战场</button>`);$('#later').onclick=()=>this.close();$('#enterTrial').onclick=()=>{if(this.e.travel('starfield'))this.close();};}
 returnCamp(){this.modal('return','归航营地','星潮旷野',`<p class="modalnote">返回晴岚驿站休整。已获得的角色、等级、物品和挑战层数与本层进度会保留在本次旅程中。</p>`,`<small>之后仍可从驿站回来。</small><button class="action gold" id="returnHome">返回晴岚驿站</button>`);$('#returnHome').onclick=()=>{if(this.e.travel('meadow'))this.close();};}
 photo(){this.modal('photo','三月七的合影时间','角色互动 · 三月七',`<div class="dialogue">${this.sprite(1)}<p>“冒险之前，先留下最棒的笑容！”<br><span class="modalnote">在白色指针进入金色区域时按下快门，连续拍下三张清晰的照片。</span></p></div><div class="gamearea"><b id="miniStatus">准备好了吗？第 1 / 3 张</b><div class="timingbar"><div class="target"></div><div class="cursor"></div></div><button class="action gold" id="snap">◎ 按下快门</button></div>`,`<small>合影完成：信用点 +20；首次额外获得专票 ×1。</small>`);this.mini=new TimingGame('photo',performance.now());$('#snap').onclick=()=>this.hitTiming();}
 fishing(){this.modal('fish','镜光湖畔 · 垂钓','湖水里藏着星星',`<p class="modalnote">观察鱼漂。在白色指针进入金色区域时收竿，钓起镜光鱼。</p><div class="gamearea"><b id="miniStatus">鱼漂轻轻晃动……</b><div class="timingbar"><div class="target"></div><div class="cursor"></div></div><button class="action gold" id="snap">⌁ 收竿</button></div>`,`<small>成功奖励：信用点 +15，有 30% 概率捞到一张专票。</small>`);this.mini=new TimingGame('fish',performance.now());$('#snap').onclick=()=>this.hitTiming();}
 hitTiming(){
  const m=this.mini;if(!(m instanceof TimingGame))return;
  const result=m.press(performance.now());if(result.ignored)return;
  const e=this.e;
  if(!result.success){$('#miniStatus').textContent=m.type==='photo'?'这张拍糊了，指针已复位。继续按快门即可！':'鱼儿溜走了，鱼漂已复位。可直接再次收竿！';this.audio('dash');return;}
  this.audio('heal');
  if(m.type==='photo'){
   if(!result.completed){$('#miniStatus').textContent=`第 ${m.n} 张拍好了！继续拍第 ${m.n+1} 张。`;return;}
   e.coins+=20;const bonus=e.photos===0;if(bonus)e.receiveTickets(1);e.photos++;
   $('#miniStatus').textContent=`三张照片都拍好了！信用点 +20${bonus?'，专票 +1':''}`;
   $('#snap').textContent='再拍一组';$('#snap').onclick=()=>{this.mini=new TimingGame('photo',performance.now());$('#miniStatus').textContent='新的一组：第 1 / 3 张';$('#snap').textContent='◎ 按下快门';$('#snap').onclick=()=>this.hitTiming();};
  }else{e.fish++;e.coins+=15;const bonus=e.random()<.3;if(bonus)e.receiveTickets(1);$('#miniStatus').textContent=`钓到镜光鱼！信用点 +15${bonus?'，专票 +1':''}。可继续收竿。`;}
  this.refresh();
 }

 slots(){this.modal('slots','星灯游艺机','驿站娱乐 · 仅使用游戏内货币',`<p class="modalnote">三个相同图案：信用点 +40、专票 ×1。两个相同：信用点 +15。没有相同图案：本次无奖励。</p><div class="gamearea"><div class="slotreels"><span>✦</span><span>☾</span><span>❖</span></div><b id="miniStatus">每次需要 10 信用点 · 当前 ${this.e.coins}</b><p><button class="action gold" id="spin">转动 · 10 信用点</button></p></div>`,`<small>没有充值、真实货币或可兑现奖励。</small>`);$('#spin').onclick=()=>{if(this.mini?.type==='slots')return;if(this.e.coins<10){$('#miniStatus').textContent='信用点不足，去探索或钓鱼赚取一些吧。';return;}this.e.coins-=10;this.mini={type:'slots',start:performance.now()};$('#spin').disabled=true;this.refresh();};}
 pause(){if(['upgrade','reveal'].includes(this.e.modal))return;if(this.e.modal){this.close();return;}this.modal('pause','旅途，稍作停留','PAUSED',`<p class="modalnote">时间已经暂停。伙伴会在原地等你。</p><div class="helpgrid"><article><b>林间的来信</b><p>已击败 ${this.e.kills} 个敌人<br>重逢 ${this.e.owned.length} / ${CHARS.length} 位伙伴</p></article><article><b>继续你的旅程</b><p>按 Esc 或点击下方按钮继续。<br>本版进度保留在当前页面，刷新将重新开始。</p></article></div>`,`<small>双区域冒险 · v0.9.3</small><button class="action gold" id="resume">继续冒险</button>`);$('#resume').onclick=()=>this.close();}
 help(){if(['upgrade','reveal'].includes(this.e.modal))return;this.modal('help','开拓者手册','HOW TO PLAY',`<div class="helpgrid"><article><b>移动与互动</b><p>方向键 / WASD 移动；点击地面也可前往。<br>空格或“闪避”按钮冲刺；鼠标右键 / Q 挥动球棒。<br>靠近人物和设施，按 E 或点“互动”。</p></article><article><b>让伙伴负责战斗</b><p>靠近敌人后，伙伴自动散开施放专属技能。战斗全程在地图上进行，结束后自动归队。只有穹会受伤，倒下后回城复活。</p></article><article><b>寻找失散的同伴</b><p>初始地图所有敌人均为 5% 掉票；无尽地图所有敌人均为 1%，每层最多掉落 ${TRIAL_TICKET_CAP} 张。拾取后先跃迁，再为新伙伴选择光锥；集齐角色后只选择光锥，库存专票也可继续使用。每次必得未拥有的角色；最多六位伙伴上场。</p></article><article><b>成长与编队</b><p>小怪固定给予 10 经验。穹首次升级需要 10 只普通怪，2–9 级逐渐增多；10–14 级每级 50 只，15–24 级每级 90 只，25→26 级需 300 只，此后每次升级需求翻倍。伙伴首次升级需 12 只，此后每级多 6 只，最高 8 级。只有穹升级会暂停三选一：自身光锥优先占左侧，另两张来自尚未满成长的上场伙伴；自身抽满后补入伙伴光锥。队伍全部满成长时，晋升直接获得一张专票。伙伴升级不抽卡。召唤演出完整结束、点击屏幕后，为刚召唤的角色选择光锥，即使其未上场。关闭召唤或集齐角色后，车票赠礼优先选择尚未满成长的上场伙伴，再选择已拥有的场下伙伴。普通、黄金光锥都最多叠加 3 次，满级后移出卡池。换人、换地图保留成长；可用牌不足时补入恢复生命与信用点的补给。点击左上穹或伙伴头像查看已获光锥。Tab 打开队伍，拖拽替换，点击角色查看详情并调整上场。</p></article><article><b>完成林间的来信</b><p>先与驿站站务员交谈 → 向东探索 → 走到地图最右端接触守门者（自动开战） → 击败首领后自动完成任务，可立即进入无尽战场。</p></article><article><b>黄金进化</b><p>黄金光锥解锁强力招式：三月七以扇形冰箭冻结敌人；丹恒用风刃与冲锋接力；黑塔化身陀螺追击并碎冰；希儿吸魂加速、残影连斩。主角的寒气与引力直接作用于敌人。多张光锥可以组合，重复获得会强化效果。</p></article><article><b>连携与冻结</b><p>异常包括冻结、减速、触电、中毒、燃烧和标记。丹恒对异常目标必定暴击；获得游龙不息后，击杀会衔接冲锋。三月七和杰帕德铺冰，黑塔获得冰封终结后可碎冰斩杀非首领。队伍击杀会触发希儿残影，再现让残影接力。普通敌人冻结时被蓝色冰块包住，停止移动、攻击和预警计时；BOSS 保持移动、攻击和预警，只将出手间隔延长 20%。角色详情可查看专属搭配建议。</p></article><article><b>旅途中的小事</b><p>与三月七合影，湖畔钓鱼，体验星灯游艺机。城镇内自动回复生命。宝箱也能获得专票。</p></article></div><div class="credits">这是《崩坏：星穹铁道》非官方同人原型。角色图为本作生成的像素改编；技能按即时玩法重新设计，非原作数值。<a href="https://sr.mihoyo.com/" target="_blank" rel="noopener">原作官网</a><br>东侧已开放长风原野、曙光高地和星风回廊。各营地清空后 16 秒刷新下一波。场景采用立体模型与实时光照，角色使用四方向逐帧动画。跃迁演出暂为角色海报。击败第一章最东端首领后，从驿站传送至第二张地图「星潮旷野」。每层有固定敌人总数，清空后挑战首领。第三层 5000 只，之后每层增加 500 只；所有敌人（含首领）血量每层变为五倍，刷怪速率每层翻倍（第三层为第一层的 4 倍速）。高层首领拥有直线横扫、火雨、瞬移和八方斩击，均有地面预警；西侧营地可以返回。刷新页面会重新开始。</div>`,`<small>方向键与鼠标即可完成全部游玩流程。</small><button class="action gold" id="understand">回到旅途</button>`);$('#understand').onclick=()=>this.close();}
 audio(kind){if(!this.soundOn)return;let now=performance.now();if(now-this.lastAudio<90)return;this.lastAudio=now;try{this.ac??=new(window.AudioContext||window.webkitAudioContext)();if(this.ac.state==='suspended')this.ac.resume();let osc=this.ac.createOscillator(),g=this.ac.createGain(),t=this.ac.currentTime;osc.connect(g);g.connect(this.ac.destination);osc.type=kind==='heal'||kind==='shield'?'sine':'triangle';let f={arrow:620,melee:210,scythe:360,laser:110,lord:150,chain:500,heal:750,shield:450,dash:240}[kind]||320;osc.frequency.setValueAtTime(f,t);osc.frequency.exponentialRampToValueAtTime(f*.5,t+.15);g.gain.setValueAtTime(.025,t);g.gain.exponentialRampToValueAtTime(.001,t+.2);osc.start();osc.stop(t+.2);}catch{}}
 update(){const e=this.e,h=e.hero;this.syncUpgrade();if(e.modal==='reveal'&&this.revealTiming?.ready(performance.now())){if(this.revealTiming.requested){this.finishReveal();}const b=$('#revealContinue');if(b){b.disabled=false;b.textContent=e.upgrades.length?'点击屏幕 · 选择成长光锥':'点击屏幕 · 继续冒险';}}$('#hp').style.width=Math.max(0,h.hp/h.maxHp*100)+'%';$('#hptext').textContent=`${Math.ceil(h.hp)} / ${h.maxHp}`;$('#xp').style.width=h.xp/xpForLevel(h.level)*100+'%';$('#level').textContent=`Lv.${h.level} · 开拓者`;$('#shield').textContent=h.shield>0?`冰垒护盾 ${Math.ceil(h.shield)}`:e.combat?'留意危险预警，保持移动。':'沿着星轨，再次相遇。';$('#region').textContent=e.lastZone;$('#dash').disabled=h.dashCd>0;$('#dash small').textContent=h.dashCd>0?h.dashCd.toFixed(1)+'s':'空格';for(const el of document.querySelectorAll('[data-cd]')){let id=+el.dataset.cd;el.style.width=Math.min(100,Math.max(0,1-e.members[id].cd/e.skillData(id).cd)*100)+'%';}const n=e.nearInteract();$('#prompt').style.display=n&&!e.modal?'block':'none';if(n)$('#prompt').textContent=`E / 点击互动 · ${n.name}`;const nearbyCamp=CAMPS.filter(c=>c.endless).sort((a,b)=>Math.hypot(a.x-h.x,a.y-h.y)-Math.hypot(b.x-h.x,b.y-h.y))[0];const es=nearbyCamp?e.campStates[nearbyCamp.id]:null;const living=e.enemies.filter(a=>a.camp===nearbyCamp?.id&&a.hp>0).length;$('#endlesshud').hidden=e.mapId==='meadow'&&h.x<2820;$('#endlesshud').textContent=e.mapId==='starfield'&&h.x<850?'归航营地 · 向东进入无尽战场':`∞ 无尽试炼 · 第 ${es?.wave||1} 波 · ${living?('剩余 '+living+' 只'):('刷新倒计时 '+Math.max(0,Math.ceil((es?.next||0)-e.time))+'s')}`;if(e.mapId==='starfield')$('#endlesshud').textContent=e.trial.started?`第 ${e.trial.number} 层 · 击败 ${e.trial.killed} / ${e.trial.goal} · 已出怪 ${e.trial.spawned} / ${e.trial.goal} · 掉票 ${e.trial.ticketsDropped} / ${TRIAL_TICKET_CAP}${e.trial.bossSpawned?' · 首领战':''}`:'归航营地 · 向东进入第 '+e.trial.number+' 层';let boss=e.enemies.find(a=>a.boss&&a.hp>0);$('#bossbar').hidden=!boss||!e.bossAwake||(e.mapId==='meadow'&&e.bossDead)||Math.hypot(boss.x-h.x,boss.y-h.y)>550;if(boss){$('#bossbar small').textContent=`${e.mapId==='starfield'?'星潮领主 · 第 '+e.trial.number+' 层':'裂界守门者'} · ${Math.max(0,Math.ceil(boss.hp)).toLocaleString()} / ${boss.maxHp.toLocaleString()}`;$('#bossbar i').style.width=Math.max(0,boss.hp/boss.maxHp*100)+'%';}
 while(e.events.length){const ev=e.events.shift();if(ev.type==='toast'){clearTimeout(this.toastTimer);$('#toast').textContent=ev.text;$('#toast').classList.add('show');this.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3800);}if(ev.type==='ticketFloat'){let box=$('#growth-ticket-float');if(!box){box=document.createElement('div');box.id='growth-ticket-float';box.setAttribute('role','status');document.body.append(box);}this.floatTickets=(this.floatTickets||0)+ev.count;box.textContent=`成长已圆满 · 专票 +${this.floatTickets}`;box.classList.remove('show');void box.offsetWidth;box.classList.add('show');clearTimeout(this.floatTimer);this.floatTimer=setTimeout(()=>{box.classList.remove('show');this.floatTickets=0;},3000);}if(ev.type==='refresh')this.refresh();if(ev.type==='chapter')this.chapterComplete();if(ev.type==='warp')this.openWarp();if(ev.type==='upgrade'&&e.modal==='upgrade'&&ev.upgrade===e.upgrades[0])this.syncUpgrade();if(ev.type==='interact'){if(ev.id==='station')this.station();if(ev.id==='return')this.returnCamp();if(ev.id==='march')this.photo();if(ev.id==='fish')this.fishing();if(ev.id==='slots')this.slots();}if(ev.type==='region'){$('#regiontoast').textContent=ev.text;$('#regiontoast').classList.add('show');clearTimeout(this.regionTimer);this.regionTimer=setTimeout(()=>$('#regiontoast').classList.remove('show'),2200);}if(ev.type==='sound')this.audio(ev.kind);}
 if(this.mini){let m=this.mini,elapsed=(performance.now()-m.start)/1000;if(m.type==='photo'||m.type==='fish'){m.pos=m.position(performance.now());const cur=$('.timingbar .cursor');if(cur)cur.style.left=(m.pos*99)+'%';}if(m.type==='slots'){const symbols=['✦','☾','❖'];document.querySelectorAll('.slotreels span').forEach((el,i)=>el.textContent=symbols[Math.floor(elapsed*14+i)%3]);if(elapsed>1.2){let result=Array.from({length:3},()=>Math.floor(e.random()*3));document.querySelectorAll('.slotreels span').forEach((el,i)=>el.textContent=symbols[result[i]]);const size=new Set(result).size;if(size===1){e.coins+=40;e.receiveTickets(1);}else if(size===2)e.coins+=15;$('#miniStatus').textContent=`${size===1?'星灯闪耀！+40 信用点，专票 ×1':size===2?'幸运的一对！+15 信用点':'这次没有连线，再接再厉。'} · 当前 ${e.coins}`;$('#spin').disabled=false;this.mini=null;this.refresh();}}}}
}
